ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS definition_version integer NOT NULL DEFAULT 1;
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS input jsonb NOT NULL DEFAULT '{}';
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS snapshot jsonb NOT NULL DEFAULT '{}';
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS next_tick timestamptz NOT NULL DEFAULT now();
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS error text;
CREATE TABLE IF NOT EXISTS workflow_steps(id text PRIMARY KEY,run_id uuid NOT NULL REFERENCES workflow_runs(id),descriptor jsonb NOT NULL,response jsonb,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS step_id text REFERENCES workflow_steps(id);
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS title text NOT NULL DEFAULT '';
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS question_id text;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS role_snapshot text;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS response_id uuid;
CREATE UNIQUE INDEX IF NOT EXISTS tasks_step_person ON tasks(step_id,assignee_id,kind);
ALTER TABLE agent_jobs ADD COLUMN IF NOT EXISTS step_id text REFERENCES workflow_steps(id);
ALTER TABLE agent_jobs ADD COLUMN IF NOT EXISTS question_id text;
ALTER TABLE agent_jobs ADD COLUMN IF NOT EXISTS action text NOT NULL DEFAULT 'research';
ALTER TABLE agent_jobs ADD COLUMN IF NOT EXISTS error text;
CREATE UNIQUE INDEX IF NOT EXISTS agent_jobs_step_question ON agent_jobs(step_id,COALESCE(question_id,''));
ALTER TABLE routing_rules ADD COLUMN IF NOT EXISTS informed_roles text[] NOT NULL DEFAULT '{}';
ALTER TABLE routing_rules ADD COLUMN IF NOT EXISTS acknowledgment_roles text[] NOT NULL DEFAULT '{}';
ALTER TABLE routing_rules ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1;
ALTER TABLE events ADD COLUMN IF NOT EXISTS user_id text;
CREATE TABLE IF NOT EXISTS invitations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),role text NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,accepted_by text);
CREATE TABLE IF NOT EXISTS webhook_receipts(id text PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS request_keys(workspace_id uuid NOT NULL REFERENCES workspaces(id),key uuid NOT NULL,hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(workspace_id,key));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL,messages jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS device_presence(workspace_id uuid REFERENCES workspaces(id),user_id text,seen_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id));
